function text(chars, style, size, opts={}){
  const t = figma.createText();
  t.fontName = {family:'Inter', style}; t.fontSize = size; t.characters = chars;
  t.fills = opts.fills || [solid(BLACK, opts.alpha!==undefined?opts.alpha:1)];
  if(opts.lh) t.lineHeight = {unit:'PERCENT', value:opts.lh};
  if(opts.align) t.textAlignHorizontal = opts.align;
  return t;
}
function frame(name){ const f=figma.createFrame(); f.name=name; f.fills=[]; f.clipsContent=true; return f; }
function al(f, mode, opts={}){
  f.layoutMode=mode;
  f.primaryAxisSizingMode=opts.pSize||'AUTO'; f.counterAxisSizingMode=opts.cSize||'AUTO';
  f.itemSpacing=opts.gap||0;
  f.paddingLeft=opts.pl||0; f.paddingRight=opts.pr||0; f.paddingTop=opts.pt||0; f.paddingBottom=opts.pb||0;
  if(opts.align) f.counterAxisAlignItems=opts.align;
  if(opts.justify) f.primaryAxisAlignItems=opts.justify;
  if(opts.wrap) f.layoutWrap='WRAP';
  return f;
}
function inst(comp, w, h){ const i = comp.createInstance(); if(w&&h) i.resize(w,h); else if(w) i.resize(w, i.height*w/comp.width); return i; }
function swapPhoto(card, photoName, w, h){
  const imgWrap = card.findOne(n => n.name==='Image');
